SELECT Version,Build,OS,Architecture,count() AS Installations FROM (SELECT properties.installation_id AS Installation,argMax(toString(properties.app_version),timestamp) AS Version,argMax(toString(properties.app_build),timestamp) AS Build,argMax(toString(properties.os_version),timestamp) AS OS,argMax(toString(properties.architecture),timestamp) AS Architecture FROM events WHERE event IN ('native_app_opened','native_app_active') AND (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY Installation) GROUP BY Version,Build,OS,Architecture ORDER BY Installations DESC LIMIT 100
